cat > popup.mjs <<'EOF'
import { chromium } from 'playwright-core';
const browser = await chromium.launch({ channel: 'chrome' });
for (const scheme of ['dark', 'light']) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 }, colorScheme: scheme });
  await page.goto(process.argv[2]);
  const trigger = page.getByRole('combobox', { name: 'Category' });
  await trigger.focus();
  await page.keyboard.press('Enter');
  await page.waitForTimeout(800);
  const info = await page.evaluate(() => {
    const lb = document.querySelector('[role="listbox"]');
    let n = lb, painted = null;
    while (n && n !== document.body) { const cs = getComputedStyle(n); if (cs.backgroundColor !== 'rgba(0, 0, 0, 0)') { painted = cs.backgroundColor; break; } n = n.parentElement; }
    return { painted, parentIsBody: n?.parentElement === document.body || null };
  });
  console.log(scheme, JSON.stringify(info));
  await page.screenshot({ path: `shots/${scheme}-select-settled.png`, clip: { x: 500, y: 520, width: 760, height: 260 } });
  await page.close();
}
await browser.close();
EOF
