cat > modes.mjs <<'EOF'
import { chromium } from 'playwright-core';
const browser = await chromium.launch({ channel: 'chrome' });
for (const [system, attr] of [['dark', 'light'], ['light', 'dark']]) {
  const page = await browser.newPage({ colorScheme: system, reducedMotion: 'reduce' });
  await page.goto(process.argv[2]);
  await page.evaluate((a) => document.documentElement.setAttribute('data-theme', a), attr);
  const v = await page.evaluate(() => {
    const cs = getComputedStyle(document.documentElement);
    const btn = getComputedStyle(document.querySelector('button[type="submit"]'));
    return { scheme: cs.colorScheme, accent: cs.getPropertyValue('--ult-color-accent').trim(), motion: cs.getPropertyValue('--ult-motion-base').trim(), btnBg: btn.backgroundColor };
  });
  console.log(`system=${system} data-theme=${attr}`, JSON.stringify(v));
  await page.close();
}
await browser.close();
EOF
